//! Schema verification and fresh installation.
//!
//! pelican-rs never migrates an existing database: it requires the schema that
//! the original panel's migrations produce (ADR-0003). For fresh installs it
//! replays a schema dump captured from the original panel (`schema/*.sql`,
//! regenerated by `scripts/schema/refresh.sh`) and records every original
//! migration in `migrations`, so the PHP panel could take the database over.

use chrono::Utc;
use sea_orm::{ConnectionTrait, DatabaseConnection, DbErr, Statement, TransactionTrait};

use crate::connect::Driver;

/// Names of all migrations of the original panel this build is compatible with.
pub const MIGRATIONS: &str = include_str!("../schema/migrations.txt");

fn schema_sql(driver: Driver) -> &'static str {
    match driver {
        Driver::Mysql => include_str!("../schema/mysql.sql"),
        Driver::Mariadb => include_str!("../schema/mariadb.sql"),
        Driver::Pgsql => include_str!("../schema/pgsql.sql"),
        Driver::Sqlite => include_str!("../schema/sqlite.sql"),
    }
}

pub fn migration_names() -> Vec<&'static str> {
    MIGRATIONS
        .lines()
        .map(str::trim)
        .filter(|l| !l.is_empty())
        .collect()
}

/// State of the database relative to the original panel's migrations.
#[derive(Debug, PartialEq, Eq)]
pub enum SchemaState {
    /// No `migrations` table: empty database.
    Empty,
    /// All known migrations applied. `unknown` lists migrations recorded in the
    /// database that this build does not know (newer panel or plugins).
    Ready { unknown: Vec<String> },
    /// Some known migrations are missing: the database was created by an older
    /// panel version and must be upgraded by the original panel first.
    Outdated { missing: Vec<String> },
}

pub async fn schema_state(db: &DatabaseConnection) -> Result<SchemaState, DbErr> {
    if !table_exists(db, "migrations").await? {
        return Ok(SchemaState::Empty);
    }
    let rows = db
        .query_all_raw(Statement::from_string(
            db.get_database_backend(),
            "SELECT migration FROM migrations",
        ))
        .await?;
    let applied: std::collections::HashSet<String> = rows
        .iter()
        .filter_map(|r| r.try_get::<String>("", "migration").ok())
        .collect();
    let known = migration_names();
    let missing: Vec<String> = known
        .iter()
        .filter(|m| !applied.contains(**m))
        .map(|m| m.to_string())
        .collect();
    if !missing.is_empty() {
        return Ok(SchemaState::Outdated { missing });
    }
    let known_set: std::collections::HashSet<&str> = known.into_iter().collect();
    let mut unknown: Vec<String> = applied
        .into_iter()
        .filter(|m| !known_set.contains(m.as_str()))
        .collect();
    unknown.sort();
    Ok(SchemaState::Ready { unknown })
}

pub async fn table_exists(db: &DatabaseConnection, table: &str) -> Result<bool, DbErr> {
    let backend = db.get_database_backend();
    let sql = match backend {
        sea_orm::DbBackend::Sqlite => {
            "SELECT name FROM sqlite_master WHERE type = 'table' AND name = ?"
        }
        sea_orm::DbBackend::MySql => {
            "SELECT table_name FROM information_schema.tables WHERE table_schema = DATABASE() AND table_name = ?"
        }
        sea_orm::DbBackend::Postgres => {
            "SELECT table_name FROM information_schema.tables WHERE table_schema = current_schema() AND table_name = $1"
        }
        _ => return Err(DbErr::Custom("unsupported backend".into())),
    };
    let row = db
        .query_one_raw(Statement::from_sql_and_values(backend, sql, [table.into()]))
        .await?;
    Ok(row.is_some())
}

/// Split a sanitized schema file into statements (quote-aware).
pub fn split_statements(sql: &str) -> Vec<String> {
    let mut out = Vec::new();
    let mut cur = String::new();
    let mut quote: Option<char> = None;
    for line in sql.lines() {
        if quote.is_none() && line.trim_start().starts_with("--") {
            continue;
        }
        for ch in line.chars() {
            cur.push(ch);
            match quote {
                Some(q) if ch == q => quote = None,
                Some(_) => {}
                None if matches!(ch, '\'' | '"' | '`') => quote = Some(ch),
                None if ch == ';' => {
                    let s = cur.trim().trim_end_matches(';').trim().to_string();
                    if !s.is_empty() {
                        out.push(s);
                    }
                    cur.clear();
                }
                None => {}
            }
        }
        cur.push('\n');
    }
    let tail = cur.trim();
    if !tail.is_empty() {
        out.push(tail.to_string());
    }
    out
}

/// Create the full schema in an EMPTY database and record all migrations.
pub async fn install_fresh(db: &DatabaseConnection, driver: Driver) -> Result<(), DbErr> {
    if schema_state(db).await? != SchemaState::Empty {
        return Err(DbErr::Custom(
            "database is not empty (a `migrations` table exists)".into(),
        ));
    }
    let backend = db.get_database_backend();
    let stmts = split_statements(schema_sql(driver));
    // MySQL DDL is not transactional; run statements in order with FK checks
    // disabled (the dump is ordered alphabetically, not by dependency).
    if matches!(driver, Driver::Mysql | Driver::Mariadb) {
        let conn = db.begin().await?; // pins one connection for the session variable
        conn.execute_unprepared("SET FOREIGN_KEY_CHECKS=0").await?;
        for s in &stmts {
            conn.execute_unprepared(s).await?;
        }
        conn.execute_unprepared("SET FOREIGN_KEY_CHECKS=1").await?;
        conn.commit().await?;
    } else {
        let txn = db.begin().await?;
        for s in &stmts {
            txn.execute_unprepared(s).await?;
        }
        txn.commit().await?;
    }

    let txn = db.begin().await?;
    let insert_migration = match backend {
        sea_orm::DbBackend::Postgres => "INSERT INTO migrations (migration, batch) VALUES ($1, 1)",
        _ => "INSERT INTO migrations (migration, batch) VALUES (?, 1)",
    };
    for name in migration_names() {
        txn.execute_raw(Statement::from_sql_and_values(
            backend,
            insert_migration,
            [name.into()],
        ))
        .await?;
    }
    // Seed rows written by the original migrations themselves.
    let now = Utc::now()
        .naive_utc()
        .format("%Y-%m-%d %H:%M:%S")
        .to_string();
    let insert_backup_host = match backend {
        sea_orm::DbBackend::Postgres => {
            "INSERT INTO backup_hosts (name, schema, configuration, created_at, updated_at) VALUES ('Local', 'wings', NULL, CAST($1 AS timestamp), CAST($2 AS timestamp))"
        }
        _ => {
            "INSERT INTO backup_hosts (name, `schema`, configuration, created_at, updated_at) VALUES ('Local', 'wings', NULL, ?, ?)"
        }
    };
    let sql = if backend == sea_orm::DbBackend::Sqlite {
        insert_backup_host.replace('`', "\"")
    } else {
        insert_backup_host.to_string()
    };
    txn.execute_raw(Statement::from_sql_and_values(
        backend,
        &sql,
        [now.clone().into(), now.into()],
    ))
    .await?;
    txn.commit().await
}
